mapper.select:
SELECT mw_num
FROM meal_week
WHERE mm_num = #{mmNum}
  AND mw_year = #{year}
  AND mw_month = #{month}
  AND mw_week = #{week}
LIMIT 1

SELECT mday_num
FROM meal_day
WHERE mw_num = #{mwNum}
  AND md_day = #{day}
LIMIT 1

mapper.insert:
INSERT INTO meal_day (
    mday_kcal,
    md_day,
    mw_num
)
VALUES (
    #{mdayKcal},
    #{mdDay},
    #{mwNum}
)

mapper.update:
UPDATE meal_day
SET mday_kcal = (
    SELECT IFNULL(SUM(md_kcal), 0)
    FROM meal_detail
    WHERE mday_num = #{mdayNum}
)
WHERE mday_num = #{mdayNum}

mapper.select:
SELECT DISTINCT ml.mk_num
FROM meal_log ml
JOIN meal_detail md ON ml.mk_num = md.mk_num
WHERE ml.user_num = #{userNum}
  AND ml.mk_meal_type = #{mkMealType}
  AND md.mday_num = #{mdayNum}

